import { Link, useSearch } from "@tanstack/react-router"
import { Eye, EyeOff } from "../../icons.gen.ts"
import { useState } from "react"
import { Button } from "@/components/ui/button"
import { Field, FieldError, FieldGroup, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import { Spinner } from "@/components/ui/spinner"
import { AuthFrame, BackToSignIn } from "@/components/auth-frame"
import { api } from "../../api.ts"
import { realmKey } from "../../config.ts"
import { describe } from "../errors.ts"
import { t } from "../i18n.ts"

// The page the password reset email links to, with its ?token; an
// invitation's too (?invite=1), which greets the person first.
export const resetPasswordSearch = (s: Record<string, unknown>) => ({ token: typeof s.token === "string" ? s.token : "", invite: s.invite === true || s.invite === 1 || s.invite === "1" })

export function ResetPasswordPage() {
  const { token, invite } = useSearch({ strict: false }) as ReturnType<typeof resetPasswordSearch>
  const [done, setDone] = useState(false)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState("")
  const [shown, setShown] = useState(false)
  if (done) {
    return (
      <AuthFrame tone="success" title={t("passwordSet")} hint={t("signInWithIt")}>
        <Button asChild size="lg" className="w-full">
          <Link to="/login" search={ { redirect: undefined } }>
            {t("signIn")}
          </Link>
        </Button>
      </AuthFrame>
    )
  }
  return (
    <AuthFrame title={invite ? t("inviteTitle") : t("setPassword")} hint={invite ? t("inviteHint") : t("resetHint")} footer={<BackToSignIn />}>
      <form
        onSubmit={async (e) => {
          e.preventDefault()
          const password = String(new FormData(e.currentTarget).get("password"))
          const identity = api.identity[realmKey] as { resetPassword?: (r: { token: string; new_password: string }) => Promise<void> }
          setBusy(true)
          setError("")
          try {
            await identity.resetPassword?.({ token, new_password: password })
            setDone(true)
          } catch (err) {
            setError(describe(err))
          } finally {
            setBusy(false)
          }
        }}
      >
        <FieldGroup className="gap-5">
          <Field data-invalid={error !== "" || undefined}>
            <FieldLabel htmlFor="password">{t("newPassword")}</FieldLabel>
            <div className="relative">
              <Input
                id="password"
                name="password"
                type={shown ? "text" : "password"}
                autoComplete="new-password"
                className="h-11 pr-11"
                required
                autoFocus
                aria-invalid={error !== "" || undefined}
              />
              <button
                type="button"
                className="absolute top-1/2 right-3 -translate-y-1/2 text-muted-foreground hover:text-foreground"
                onClick={() => setShown((s) => !s)}
                aria-label={shown ? t("hidePassword") : t("showPassword")}
              >
                {shown ? <EyeOff className="size-4" /> : <Eye className="size-4" />}
              </button>
            </div>
            {error && <FieldError>{error}</FieldError>}
          </Field>
          <Button type="submit" size="lg" className="w-full" disabled={busy}>
            {busy && <Spinner />}
            {t("setPassword")}
          </Button>
        </FieldGroup>
      </form>
    </AuthFrame>
  )
}
